import type Binding from "../binding";
import TraversalContext from "../../context";
import splitExportDeclaration from "@babel/helper-split-export-declaration";
import * as t from "@babel/types";
import type { NodePath, Visitor } from "../..";
import { requeueComputedKeyAndDecorators } from "@babel/helper-environment-visitor";
import { traverseNode } from "../../traverse-node";
import { explode } from "../../visitors";

const renameVisitor: Visitor<Renamer> = {
  ReferencedIdentifier({ node }, state) {
    if (node.name === state.oldName) {
      node.name = state.newName;
    }
  },

  Scope(path, state) {
    if (
      !path.scope.bindingIdentifierEquals(
        state.oldName,
        state.binding.identifier,
      )
    ) {
      path.skip();
      if (path.isMethod()) {
        requeueComputedKeyAndDecorators(path);
      }
    }
  },

  "AssignmentExpression|Declaration|VariableDeclarator"(
    path: NodePath<t.AssignmentPattern | t.Declaration | t.VariableDeclarator>,
    state,
  ) {
    if (path.isVariableDeclaration()) return;
    const ids = path.getOuterBindingIdentifiers();

    for (const name in ids) {
      if (name === state.oldName) ids[name].name = state.newName;
    }
  },
};

export default class Renamer {
  constructor(binding: Binding, oldName: string, newName: string) {
    this.newName = newName;
    this.oldName = oldName;
    this.binding = binding;
  }

  declare oldName: string;
  declare newName: string;
  declare binding: Binding;

  maybeConvertFromExportDeclaration(parentDeclar: NodePath) {
    const maybeExportDeclar = parentDeclar.parentPath;

    if (!maybeExportDeclar.isExportDeclaration()) {
      return;
    }

    if (maybeExportDeclar.isExportDefaultDeclaration()) {
      const { declaration } = maybeExportDeclar.node;
      if (t.isDeclaration(declaration) && !declaration.id) {
        return;
      }
    }

    if (maybeExportDeclar.isExportAllDeclaration()) {
      return;
    }

    splitExportDeclaration(
      maybeExportDeclar as NodePath<
        Exclude<t.ExportDeclaration, t.ExportAllDeclaration>
      >,
    );
  }

  maybeConvertFromClassFunctionDeclaration(path: NodePath) {
    return path; // TODO

    // // retain the `name` of a class/function declaration

    // if (!path.isFunctionDeclaration() && !path.isClassDeclaration()) return;
    // if (this.binding.kind !== "hoisted") return;

    // path.node.id = identifier(this.oldName);
    // path.node._blockHoist = 3;

    // path.replaceWith(
    //   variableDeclaration("let", [
    //     variableDeclarator(identifier(this.newName), toExpression(path.node)),
    //   ]),
    // );
  }

  maybeConvertFromClassFunctionExpression(path: NodePath) {
    return path; // TODO

    // // retain the `name` of a class/function expression

    // if (!path.isFunctionExpression() && !path.isClassExpression()) return;
    // if (this.binding.kind !== "local") return;

    // path.node.id = identifier(this.oldName);

    // this.binding.scope.parent.push({
    //   id: identifier(this.newName),
    // });

    // path.replaceWith(
    //   assignmentExpression("=", identifier(this.newName), path.node),
    // );
  }

  rename(/* Babel 7 - block?: t.Pattern | t.Scopable */) {
    const { binding, oldName, newName } = this;
    const { scope, path } = binding;

    let parentDeclar: NodePath | null = null;
    let current: NodePath | null = path;
    while (current) {
      if (
        current.isDeclaration() ||
        current.isFunctionExpression() ||
        current.isClassExpression()
      ) {
        parentDeclar = current;
        break;
      }
      current = current.parentPath;
    }

    if (parentDeclar) {
      const search: Array<t.Node | null | undefined> = [parentDeclar.node];
      const bindingIds: Record<string, t.Identifier> = Object.create(null);
      while (search.length) {
        const extracted = search.shift();
        if (!extracted) {
          continue;
        }
        const identifierKeys =
          // @ts-expect-error keys do not cover every AST type
          t.getBindingIdentifiers.keys[extracted.type];
        if (t.isIdentifier(extracted)) {
          bindingIds[extracted.name] = extracted;
          continue;
        }
        if (t.isExportDeclaration(extracted)) {
          if (!t.isExportAllDeclaration(extracted)) {
            if (t.isDeclaration(extracted.declaration)) {
              search.push(extracted.declaration);
            }
          }
          continue;
        }
        if (t.isFunctionDeclaration(extracted)) {
          if (extracted.id) {
            search.push(extracted.id);
          }
          continue;
        }
        if (t.isFunctionExpression(extracted)) {
          continue;
        }
        if (identifierKeys) {
          for (
            let keyIndex = 0;
            keyIndex < identifierKeys.length;
            keyIndex++
          ) {
            const identifierKey = identifierKeys[keyIndex];
            const nestedNodes =
              // @ts-expect-error key is from the identifier map
              extracted[identifierKey] as t.Node | t.Node[] | null | undefined;
            if (nestedNodes) {
              if (Array.isArray(nestedNodes)) {
                for (const nestedNode of nestedNodes) {
                  if (nestedNode) {
                    search.push(nestedNode);
                  }
                }
              } else {
                search.push(nestedNodes);
              }
            }
          }
        }
      }

      if (bindingIds[oldName] === binding.identifier) {
        const maybeExportDeclar = parentDeclar.parentPath;
        if (maybeExportDeclar.isExportDeclaration()) {
          if (maybeExportDeclar.isExportDefaultDeclaration()) {
            const { declaration } = maybeExportDeclar.node;
            if (t.isDeclaration(declaration) && !declaration.id) {
              // Anonymous default function/class declarations keep their export shape.
            } else if (!maybeExportDeclar.isExportAllDeclaration()) {
              const declarationPath = maybeExportDeclar.get("declaration");
              const standaloneDeclaration =
                declarationPath.isFunctionDeclaration() ||
                declarationPath.isClassDeclaration();
              const declarationScope = declarationPath.isScope()
                ? declarationPath.scope.parent
                : declarationPath.scope;
              // @ts-expect-error id is only present on functions/classes
              let exportedId = declarationPath.node.id as
                | t.Identifier
                | undefined;
              let needBindingRegistration = false;

              if (!exportedId) {
                needBindingRegistration = true;
                const uidBase = t
                  .toIdentifier("default")
                  .replace(/^_+/, "")
                  .replace(/[0-9]+$/g, "");
                let uid: string;
                let uidIndex = 1;
                do {
                  if (uidIndex > 1) {
                    uid = `_${uidBase}${uidIndex}`;
                  } else {
                    uid = `_${uidBase}`;
                  }
                  uidIndex++;
                } while (
                  declarationScope.hasLabel(uid) ||
                  declarationScope.hasBinding(uid) ||
                  declarationScope.hasGlobal(uid) ||
                  declarationScope.hasReference(uid)
                );
                const programScope = declarationScope.getProgramParent();
                programScope.references[uid] = true;
                programScope.uids[uid] = true;
                exportedId = t.identifier(uid);

                if (
                  standaloneDeclaration ||
                  declarationPath.isFunctionExpression() ||
                  declarationPath.isClassExpression()
                ) {
                  // @ts-expect-error assigning generated id on function/class
                  declarationPath.node.id = t.cloneNode(exportedId);
                }
              }

              const updatedDeclaration = standaloneDeclaration
                ? declarationPath.node
                : t.variableDeclaration("var", [
                    t.variableDeclarator(
                      t.cloneNode(exportedId),
                      // @ts-expect-error default expression is not a declaration
                      declarationPath.node,
                    ),
                  ]);
              const updatedExportDeclaration = t.exportNamedDeclaration(null, [
                t.exportSpecifier(
                  t.cloneNode(exportedId),
                  t.identifier("default"),
                ),
              ]);
              maybeExportDeclar.insertAfter(updatedExportDeclaration);
              maybeExportDeclar.replaceWith(updatedDeclaration);
              if (needBindingRegistration) {
                declarationScope.registerDeclaration(maybeExportDeclar);
              }
            }
          } else if (!maybeExportDeclar.isExportAllDeclaration()) {
            if (maybeExportDeclar.get("specifiers").length > 0) {
              throw new Error(
                "It doesn't make sense to split exported specifiers.",
              );
            } else {
              const declarationPath = maybeExportDeclar.get("declaration");
              const exportedBindingIdentifiers =
                declarationPath.getOuterBindingIdentifiers();
              const specifiers = [];
              for (const exportedName of Object.keys(
                exportedBindingIdentifiers,
              )) {
                if (exportedName) {
                  specifiers.push(
                    t.exportSpecifier(
                      t.identifier(exportedName),
                      t.identifier(exportedName),
                    ),
                  );
                }
              }
              const aliasDeclar = t.exportNamedDeclaration(null, specifiers);
              maybeExportDeclar.insertAfter(aliasDeclar);
              maybeExportDeclar.replaceWith(declarationPath.node);
            }
          }
        }
      }
    }

    const blockToTraverse = process.env.BABEL_8_BREAKING
      ? scope.block
      : (arguments[0] as t.Pattern | t.Scopable) || scope.block;
    const visitor = explode(renameVisitor);
    const visitorKeys = t.VISITOR_KEYS[blockToTraverse.type];
    const skipKeys: Record<string, boolean> = { discriminant: true };

    if (visitorKeys) {
      const context = new TraversalContext(scope, visitor, this, scope.path);
      for (const visitorKey of visitorKeys) {
        if (skipKeys[visitorKey]) {
          continue;
        }
        const childNodes = (blockToTraverse as any)[visitorKey] as
          | t.Node
          | t.Node[]
          | null
          | undefined;
        if (!childNodes) {
          continue;
        }
        const isList = Array.isArray(childNodes);
        const candidates: Array<t.Node | null | undefined> = isList
          ? childNodes
          : [childNodes];
        if (isList && childNodes.length === 0) {
          continue;
        }
        const queue: NodePath[] = [];
        for (let childIndex = 0; childIndex < candidates.length; childIndex++) {
          const child = candidates[childIndex];
          if (!child) {
            continue;
          }
          const opts = context.opts as Visitor;
          let shouldVisitChild = false;
          if (opts.enter || opts.exit || (opts as any)[child.type]) {
            shouldVisitChild = true;
          } else {
            const childKeys = t.VISITOR_KEYS[child.type];
            if (childKeys) {
              for (const childKey of childKeys) {
                if ((child as any)[childKey]) {
                  shouldVisitChild = true;
                  break;
                }
              }
            }
          }
          if (shouldVisitChild) {
            if (isList) {
              queue.push(
                context.create(
                  blockToTraverse,
                  childNodes,
                  childIndex,
                  visitorKey,
                ),
              );
            } else {
              queue.push(
                context.create(blockToTraverse, blockToTraverse, visitorKey),
              );
            }
          }
        }

        if (queue.length) {
          context.queue = queue;
          context.priorityQueue = [];
          const visited = new WeakSet();
          let stop = false;
          for (const childPath of queue) {
            childPath.resync();
            if (
              childPath.contexts.length === 0 ||
              childPath.contexts[childPath.contexts.length - 1] !== context
            ) {
              childPath.pushContext(context);
            }
            if (childPath.key === null) {
              continue;
            }
            const queuedNode = childPath.node;
            if (queuedNode) {
              if (visited.has(queuedNode)) {
                continue;
              }
              visited.add(queuedNode);
            }
            if (childPath.visit()) {
              stop = true;
              break;
            }
            if (context.priorityQueue.length) {
              stop = context.visitQueue(context.priorityQueue);
              context.priorityQueue = [];
              context.queue = queue;
              if (stop) {
                break;
              }
            }
          }
          for (const childPath of queue) {
            childPath.popContext();
          }
          context.queue = null;
          if (stop) {
            break;
          }
        }
      }
    }

    if (process.env.BABEL_8_BREAKING) {
      scope.removeOwnBinding(oldName);
      scope.bindings[newName] = binding;
      this.binding.identifier.name = newName;
    } else if (!arguments[0]) {
      scope.removeOwnBinding(oldName);
      scope.bindings[newName] = binding;
      this.binding.identifier.name = newName;
    }

    if (parentDeclar) {
      this.maybeConvertFromClassFunctionDeclaration(path);
      this.maybeConvertFromClassFunctionExpression(path);
    }
  }
}

